import{readFile,writeFile,mkdir,cp,readdir,stat}from'node:fs/promises';import path from'node:path';import{fileURLToPath}from'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),target=path.resolve(process.argv[2]||'out/RustJan');await stat(path.join(target,'RustJan.exe'));
for(const folder of ['conf','logs','research','tests','node_modules','.git']){try{await stat(path.join(target,folder));throw Error('Private/development folder in bundle: '+folder);}catch(e){if(e.code!=='ENOENT')throw e;}}
for(const file of ['README.md','README.et.md','THIRD_PARTY_NOTICES.md','CHANGELOG.md','SECURITY.md']){let text=await readFile(path.join(root,file),'utf8');if(file.startsWith('README'))text=text.replaceAll('](LICENSE)','](LICENSE-RustJan.txt)');await writeFile(path.join(target,file),text);}
await cp(path.join(root,'LICENSE'),path.join(target,'LICENSE-RustJan.txt'));await cp(path.join(root,'docs'),path.join(target,'docs'),{recursive:true});await mkdir(path.join(target,'licenses'),{recursive:true});await cp(path.join(root,'public','flags','LICENSE'),path.join(target,'licenses','flag-icons-LICENSE.txt'));await cp(path.join(root,'data','SOURCES.txt'),path.join(target,'licenses','IP-country-SOURCES.txt'));console.log('User guides and license notices added to clean portable bundle.');
